-- AgentOS schema v0
-- Mirrors the Anthropic Managed Agents resources (PRD §4, §6A) plus AgentOS extensions.
-- IDs are CMA-style text ids generated by the API (agent_01…, sesn_01…), not uuids.
-- Every row belongs to a workspace; row-level security limits access to workspace members.

create schema if not exists agentos;

-- ---------------------------------------------------------------- tenancy

create table agentos.workspaces (
  id          text primary key,
  name        text not null,
  created_at  timestamptz not null default now()
);

create table agentos.workspace_members (
  workspace_id text not null references agentos.workspaces(id) on delete cascade,
  user_id      uuid not null references auth.users(id) on delete cascade,
  role         text not null check (role in ('admin', 'developer', 'viewer')),
  created_at   timestamptz not null default now(),
  primary key (workspace_id, user_id)
);

create or replace function agentos.is_member(ws text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from agentos.workspace_members m
    where m.workspace_id = ws and m.user_id = auth.uid()
  );
$$;

create table agentos.api_keys (
  id           text primary key,                       -- aok_…
  workspace_id text not null references agentos.workspaces(id) on delete cascade,
  name         text not null,
  key_hash     text not null unique,
  hint         text not null,
  created_by   uuid references auth.users(id),
  created_at   timestamptz not null default now(),
  last_used_at timestamptz,
  revoked_at   timestamptz
);

-- ---------------------------------------------------- model provider (ext)

create table agentos.provider_settings (
  workspace_id    text not null references agentos.workspaces(id) on delete cascade,
  provider        text not null default 'openrouter' check (provider = 'openrouter'),
  key_secret_id   uuid,                                 -- vault.secrets id; key never stored in plain text
  key_hint        text,
  status          text not null default 'unknown' check (status in ('unknown', 'valid', 'invalid')),
  routing         jsonb not null default '{}'::jsonb,   -- default provider routing preferences
  last_checked_at timestamptz,
  primary key (workspace_id, provider)
);

create table agentos.models_cache (
  id                   text primary key,                -- OpenRouter slug
  name                 text not null,
  context_length       integer,
  pricing              jsonb not null,
  supported_parameters text[] not null default '{}',
  input_modalities     text[] not null default '{text}',
  supports_tools       boolean generated always as ('tools' = any(supported_parameters)) stored,
  updated_at           timestamptz not null default now()
);

-- ----------------------------------------------------------------- agents

create table agentos.agents (
  id             text primary key,                      -- agent_…
  workspace_id   text not null references agentos.workspaces(id) on delete cascade,
  slug           text,                                  -- stable across local/cloud (push/pull)
  latest_version integer not null default 1,
  created_by     text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  archived_at    timestamptz,
  unique (workspace_id, slug)
);

create table agentos.agent_versions (
  agent_id   text not null references agentos.agents(id) on delete cascade,
  version    integer not null,
  spec       jsonb not null,                            -- name, model, system, tools, mcp_servers, skills, multiagent, metadata
  created_by text,
  created_at timestamptz not null default now(),
  primary key (agent_id, version)
);

-- ----------------------------------------------------------- environments

create table agentos.environments (
  id           text primary key,                        -- env_…
  workspace_id text not null references agentos.workspaces(id) on delete cascade,
  name         text not null,
  description  text,
  config       jsonb not null,                          -- {type: cloud|self_hosted|local, networking, packages}
  metadata     jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  archived_at  timestamptz
);

-- ----------------------------------------------------------------- vaults

create table agentos.vaults (
  id           text primary key,                        -- vlt_…
  workspace_id text not null references agentos.workspaces(id) on delete cascade,
  name         text not null,
  metadata     jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  archived_at  timestamptz
);

create table agentos.credentials (
  id            text primary key,                       -- vcrd_…
  vault_id      text not null references agentos.vaults(id) on delete cascade,
  name          text,
  auth_type     text not null check (auth_type in ('mcp_oauth', 'static_bearer', 'environment_variable')),
  secret_id     uuid,                                   -- vault.secrets id
  config        jsonb not null default '{}'::jsonb,     -- mcp_server_url, allowed_hosts, injection_location…
  scope         jsonb not null default '{}'::jsonb,     -- AgentOS ext: {agent_ids?, run_ids?}
  last_used_at  timestamptz,
  created_at    timestamptz not null default now(),
  archived_at   timestamptz
);

-- --------------------------------------------------------------- sessions

create table agentos.workers (                           -- AgentOS ext: laptops / VPC workers
  id           text primary key,                        -- wrk_…
  workspace_id text not null references agentos.workspaces(id) on delete cascade,
  name         text not null,
  kind         text not null check (kind in ('laptop', 'vpc')),
  capabilities jsonb not null default '{}'::jsonb,
  last_seen_at timestamptz,
  created_at   timestamptz not null default now()
);

create table agentos.sessions (
  id             text primary key,                      -- sesn_…
  workspace_id   text not null references agentos.workspaces(id) on delete cascade,
  agent_id       text not null references agentos.agents(id),
  agent_version  integer not null,
  environment_id text not null references agentos.environments(id),
  deployment_id  text,
  title          text,
  status         text not null default 'idle' check (status in ('idle', 'running', 'rescheduling', 'terminated')),
  runs_on        text not null default 'local',          -- AgentOS ext: local | cloud | worker:<id>
  vault_ids      text[] not null default '{}',
  budget_cents   bigint,
  usage          jsonb not null default '{"input_tokens":0,"output_tokens":0,"cache_read_input_tokens":0,"cache_creation_input_tokens":0,"cost_usd":"0","active_seconds":0}'::jsonb,
  metadata       jsonb not null default '{}'::jsonb,
  created_by     text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  archived_at    timestamptz
);
create index sessions_ws_created on agentos.sessions (workspace_id, created_at desc);

create table agentos.session_events (
  id           text not null,                           -- sevt_…
  session_id   text not null references agentos.sessions(id) on delete cascade,
  seq          bigint not null,
  thread_id    text,
  type         text not null,
  payload      jsonb not null,
  created_at   timestamptz not null default now(),
  processed_at timestamptz,
  primary key (session_id, seq)
);
create unique index session_events_id on agentos.session_events (id);

create table agentos.threads (
  id              text primary key,
  session_id      text not null references agentos.sessions(id) on delete cascade,
  parent_thread   text,
  workflow_run_id text,
  name            text,
  agent_snapshot  jsonb not null,
  status          text not null default 'idle',
  context_tokens  integer not null default 0,
  cost_usd        numeric(12, 6) not null default 0,
  created_at      timestamptz not null default now()
);

create table agentos.workflow_runs (
  id         text primary key,                          -- wrun_…
  session_id text not null references agentos.sessions(id) on delete cascade,
  name       text,
  goal       text,
  phases     jsonb not null default '[]'::jsonb,
  status     text not null default 'running',
  created_at timestamptz not null default now(),
  ended_at   timestamptz
);

create table agentos.tool_calls (
  id          text primary key,                         -- the sevt_ id of the tool_use event
  session_id  text not null references agentos.sessions(id) on delete cascade,
  thread_id   text,
  tool        text not null,
  kind        text not null check (kind in ('builtin', 'mcp', 'custom')),
  permission  text,
  decision    text,                                     -- allow | ask | deny + reason code
  status      text not null default 'pending',          -- completed | failed | denied | interrupted
  duration_ms integer,
  created_at  timestamptz not null default now()
);

create table agentos.outcomes (
  id             text primary key,
  session_id     text not null references agentos.sessions(id) on delete cascade,
  description    text not null,
  rubric         jsonb not null,
  max_iterations integer not null default 3 check (max_iterations between 1 and 20),
  result         text,                                  -- satisfied | unsatisfied | in_progress
  created_at     timestamptz not null default now()
);

create table agentos.outcome_evaluations (
  outcome_id  text not null references agentos.outcomes(id) on delete cascade,
  iteration   integer not null,
  verdict     text not null,
  criteria    jsonb not null,                           -- [{criterion, met, evidence}]
  explanation text,
  created_at  timestamptz not null default now(),
  primary key (outcome_id, iteration)
);

-- ----------------------------------------------------------------- memory

create table agentos.memory_stores (
  id           text primary key,                        -- memstore_…
  workspace_id text not null references agentos.workspaces(id) on delete cascade,
  name         text not null,
  description  text,
  metadata     jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  archived_at  timestamptz
);

create table agentos.memories (
  id              text primary key,                     -- mem_…
  memory_store_id text not null references agentos.memory_stores(id) on delete cascade,
  path            text not null,
  content         text not null check (octet_length(content) <= 102400),
  content_sha256  text not null,
  updated_by      text,                                 -- sesn_… or user/api key
  updated_at      timestamptz not null default now(),
  unique (memory_store_id, path)
);

create table agentos.memory_versions (
  id              text primary key,                     -- memver_…
  memory_store_id text not null references agentos.memory_stores(id) on delete cascade,
  memory_id       text not null,
  operation       text not null check (operation in ('created', 'modified', 'deleted')),
  path            text,
  content         text,
  content_sha256  text,
  actor           text,
  session_id      text,
  redacted_at     timestamptz,
  created_at      timestamptz not null default now()
);

-- ---------------------------------------------------------- files, skills

create table agentos.files (
  id           text primary key,                        -- file_…
  workspace_id text not null references agentos.workspaces(id) on delete cascade,
  filename     text not null,
  mime_type    text,
  size_bytes   bigint not null,
  storage_path text not null,                           -- Supabase Storage object path
  session_id   text,                                    -- set for session outputs
  created_at   timestamptz not null default now()
);

create table agentos.skills (
  id           text primary key,                        -- skill_…
  workspace_id text not null references agentos.workspaces(id) on delete cascade,
  name         text not null,
  source       text not null default 'custom',
  created_at   timestamptz not null default now()
);

create table agentos.skill_versions (
  skill_id     text not null references agentos.skills(id) on delete cascade,
  version      text not null,
  storage_path text not null,
  created_at   timestamptz not null default now(),
  primary key (skill_id, version)
);

-- ------------------------------------------------------------ deployments

create table agentos.deployments (
  id             text primary key,                      -- depl_…
  workspace_id   text not null references agentos.workspaces(id) on delete cascade,
  name           text not null,
  agent_id       text not null references agentos.agents(id),
  agent_version  integer,                               -- null = latest
  environment_id text not null references agentos.environments(id),
  initial_events jsonb not null,
  schedule       jsonb,                                 -- {type: cron, expression, timezone}
  session_config jsonb not null default '{}'::jsonb,    -- resources, vault_ids, budget
  runs_on        text not null default 'cloud',         -- AgentOS ext
  status         text not null default 'active' check (status in ('active', 'paused', 'archived')),
  paused_reason  text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create table agentos.deployment_runs (
  id            text primary key,                       -- drun_…
  deployment_id text not null references agentos.deployments(id) on delete cascade,
  trigger       jsonb not null,                         -- {type: manual|schedule|webhook}
  session_id    text,
  error         jsonb,                                  -- {type: environment_archived|…}
  created_at    timestamptz not null default now()
);

-- ------------------------------------------------- webhooks, audit (ext)

create table agentos.webhook_endpoints (
  id           text primary key,
  workspace_id text not null references agentos.workspaces(id) on delete cascade,
  url          text not null,
  events       text[] not null,
  secret_id    uuid,
  enabled      boolean not null default true,
  created_at   timestamptz not null default now()
);

create table agentos.audit_log (
  id           bigint generated always as identity primary key,
  workspace_id text not null references agentos.workspaces(id) on delete cascade,
  actor_type   text not null check (actor_type in ('user', 'api_key', 'agent', 'system')),
  actor_id     text not null,
  action       text not null,
  target       text,
  details      jsonb not null default '{}'::jsonb,
  prev_hash    text,
  hash         text not null,
  created_at   timestamptz not null default now()
);

-- ------------------------------------------------------- row-level security
-- The API uses the service role (bypasses RLS). These policies protect direct
-- client access (e.g. Supabase Realtime subscriptions from the Console).

do $$
declare t text;
begin
  foreach t in array array[
    'api_keys','provider_settings','agents','environments','vaults','workers',
    'sessions','memory_stores','files','skills','deployments','webhook_endpoints','audit_log'
  ] loop
    execute format('alter table agentos.%I enable row level security', t);
    execute format(
      'create policy %I on agentos.%I for select using (agentos.is_member(workspace_id))',
      t || '_member_read', t);
  end loop;
end $$;

alter table agentos.workspaces enable row level security;
create policy workspaces_member_read on agentos.workspaces for select using (agentos.is_member(id));

alter table agentos.workspace_members enable row level security;
create policy members_self_read on agentos.workspace_members for select using (user_id = auth.uid());

alter table agentos.session_events enable row level security;
create policy session_events_member_read on agentos.session_events for select using (
  exists (select 1 from agentos.sessions s where s.id = session_id and agentos.is_member(s.workspace_id))
);

-- Child tables without workspace_id: deny direct access (API only).
alter table agentos.agent_versions    enable row level security;
alter table agentos.credentials       enable row level security;
alter table agentos.threads           enable row level security;
alter table agentos.workflow_runs     enable row level security;
alter table agentos.tool_calls        enable row level security;
alter table agentos.outcomes          enable row level security;
alter table agentos.outcome_evaluations enable row level security;
alter table agentos.memories          enable row level security;
alter table agentos.memory_versions   enable row level security;
alter table agentos.skill_versions    enable row level security;
alter table agentos.deployment_runs   enable row level security;
alter table agentos.models_cache      enable row level security;
create policy models_cache_read on agentos.models_cache for select using (true);
